#!/usr/bin/env bash`nset -euo pipefail`n`n# Patch CMake version requirements`nsed -i "s|find_package(hyprwayland-scanner 0.4.4 REQUIRED)|find_package(hyprwayland-scanner 0.4.0 REQUIRED)|g" "$KUMO_SOURCE/CMakeLists.txt"`nsed -i "s/hyprlang>=0.6.0/hyprlang>=0.4.0/g" "$KUMO_SOURCE/CMakeLists.txt"`nsed -i "s/hyprutils>=0.2.0/hyprutils>=0.1.0/g" "$KUMO_SOURCE/CMakeLists.txt"`n`nSYSROOT="$KUMO_BUILD/../sysroot"`ncmake -S "$KUMO_SOURCE" -B "$KUMO_BUILD" \`n  -DCMAKE_TOOLCHAIN_FILE="$KUMO_BUILD/kumo-toolchain.cmake" \`n  -DCMAKE_INSTALL_PREFIX=/usr \`n  -DCMAKE_BUILD_TYPE=Release \`n  -DEGL_INCLUDE_DIR="$SYSROOT/usr/include/EGL" \`n  -DEGL_LIBRARY="$SYSROOT/usr/lib/libEGL.so" \`n  -DGLES3_INCLUDE_DIR="$SYSROOT/usr/include/GLES3" \`n  -DGLES3_LIBRARY="$SYSROOT/usr/lib/libGLESv3.so" \`n  -DOPENGL_egl_LIBRARY="$SYSROOT/usr/lib/libEGL.so" \`n  -DOPENGL_gles3_LIBRARY="$SYSROOT/usr/lib/libGLESv3.so"`n`ncmake --build "$KUMO_BUILD" -j"$(getconf _NPROCESSORS_ONLN)"`n`nDESTDIR="$KUMO_DESTDIR" cmake --install "$KUMO_BUILD"`n`necho "[hyprlock] Package staged successfully"
